package marked

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// cjkCase is one case of the CJK friendly reference.
type cjkCase struct {
	Markdown string `json:"markdown"`
	Tokens   []any  `json:"tokens"`
}

// TestCjkFriendlyParity compares the CJK friendly tokenizer of the port
// against marked-cjk-friendly 0.1.2.
//
// The reference is generated by scripts/marked-cjk-reference.mjs.
func TestCjkFriendlyParity(t *testing.T) {
	cases := loadCjkCases(t)

	for _, testCase := range cases {
		testCase := testCase
		t.Run(testCase.Markdown, func(t *testing.T) {
			instance := New(MarkedExtension{
				Tokenizer: CjkFriendly(),
			})
			tokens := instance.Lexer(testCase.Markdown, nil)

			got := canonicalTokens(tokens)
			want := testCase.Tokens

			if normalizeJSON(got) != normalizeJSON(want) {
				t.Fatalf("token stream differs for %q\ngot:  %s\nwant: %s",
					testCase.Markdown, compactJSON(got), compactJSON(want))
			}
		})
	}
}

// TestCjkFriendlyWithoutExtension checks that the port falls back to the
// built in emphasis rules when the extension is not registered.
func TestCjkFriendlyWithoutExtension(t *testing.T) {
	cases := loadCjkCases(t)

	for _, testCase := range cases {
		testCase := testCase
		t.Run(testCase.Markdown, func(t *testing.T) {
			tokens, _ := Lex(testCase.Markdown, nil)
			got := canonicalTokens(tokens)

			// The reference holds the tokens of the CJK friendly extension.
			// Without the extension the port may differ, but it must still
			// produce a token stream that does not lose text.
			text := flattenTokenText(tokens)
			if text == "" && testCase.Markdown != "" {
				t.Fatalf("token stream lost the text of %q", testCase.Markdown)
			}
			_ = got
		})
	}
}

// TestCjkConstantMatchesUpstream checks that the CJK constant of the port
// holds the code point ranges of the extension.
func TestCjkConstantMatchesUpstream(t *testing.T) {
	parsed := parseCjkConstant(cjkConstant)
	if len(parsed) != len(cjkRanges) {
		t.Fatalf("cjk ranges differ: %d parsed, %d listed", len(parsed), len(cjkRanges))
	}
	for i, r := range parsed {
		if r != cjkRanges[i] {
			t.Fatalf("cjk range %d differs: %v parsed, %v listed", i, r, cjkRanges[i])
		}
	}
}

// TestCjkClassMatchesConstant checks that the character classes of the
// extension hold the CJK constant.
func TestCjkClassMatchesConstant(t *testing.T) {
	for _, source := range []string{
		cjkPunctSource,
		cjkPunctSpaceSource,
		cjkNotPunctSpaceSource,
		cjkDelPunctSource,
		cjkDelPunctSpaceSource,
		cjkDelNotPunctSpaceSource,
		cjkPunctGfmSource,
		cjkPunctSpaceGfmSource,
		cjkNotPunctSpaceGfmSource,
		punctuationCjkSource,
	} {
		if !contains(source, cjkConstant) {
			t.Fatalf("class does not hold the CJK constant: %s", source)
		}
	}
}

// TestCjkCodePoints checks the code points that the extension treats as CJK.
func TestCjkCodePoints(t *testing.T) {
	cjk := []string{"中", "文", "。", "、", "あ", "ア", "한", "가", "\U00020000"}
	for _, s := range cjk {
		if !isCjk(s) {
			t.Fatalf("%q is not treated as CJK", s)
		}
	}
	notCJK := []string{"a", "1", " ", "*", "_", "é", "→"}
	for _, s := range notCJK {
		if isCjk(s) {
			t.Fatalf("%q is treated as CJK", s)
		}
	}
}

// loadCjkCases reads the CJK friendly reference.
func loadCjkCases(t *testing.T) []cjkCase {
	t.Helper()
	path := filepath.Join("testdata", "cjk.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read reference: %v", err)
	}
	var cases []cjkCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatalf("parse reference: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("reference is empty")
	}
	return cases
}

// flattenTokenText returns the text of every token of a token stream.
func flattenTokenText(tokens []Token) string {
	out := ""
	for i := range tokens {
		out += tokens[i].Text
		out += flattenTokenText(tokens[i].Tokens)
		for j := range tokens[i].Items {
			out += flattenTokenText(tokens[i].Items[j].Tokens)
		}
	}
	return out
}

// contains reports whether a string holds a substring.
func contains(haystack string, needle string) bool {
	return strings.Contains(haystack, needle)
}
